from pathlib import Path
import yaml,re,json
configs=list(Path("config").glob("*.yaml"))
for p in configs: yaml.safe_load(p.read_text(encoding="utf-8"))
samples=0
for p in Path("specs").rglob("*.md"):
 for code in re.findall(r"```yaml\s*\n(.*?)\n```",p.read_text(encoding="utf-8"),re.S):
  yaml.safe_load(code); samples+=1
print(json.dumps({"configs":len(configs),"yaml_examples":samples}))
